pragma solidity ^0.8.24;
import "forge-std/Test.sol";
import "../fixtures/Pool.sol";

contract MaliciousToken is IERC20 {
    Pool public pool;
    bool public reentered;
    // ... standard ERC20 storage/balanceOf/approve omitted for brevity ...
    function transfer(address to, uint256 amount) external returns (bool) {
        if (!reentered && msg.sender == address(pool)) {
            reentered = true;
            // Re-enter swap() while Pool's reserveA/reserveB still reflect the PRE-swap
            // state (the vulnerable window) — this is the actual exploit, not a revert probe.
            pool.swap(address(this), 1);
        }
        _balances[to] += amount;
        return true;
    }
    // ...
}

contract PoolReentrancyTest is Test {
    function test_reentrancy_cannotDrainBeyondRealBalance() public {
        // setup: deploy Pool with a normal tokenA and a MaliciousToken as tokenB,
        // fund both, addLiquidity normally, then have an attacker call swap()
        // with tokenB, triggering the malicious transfer() reentrant path.
        // ...
        uint256 poolTokenABalanceAfter = tokenA.balanceOf(address(pool));
        uint256 poolTokenBBalanceAfter = tokenB.balanceOf(address(pool));
        // THE REAL INVARIANT (not 'did it revert'): the pool must never be left holding
        // less than its own recorded reserves claim — that's what 'drained via reentrancy'
        // actually means, and it's what a shallow revert-only test would miss entirely if
        // the reentrant call happens to succeed without reverting.
        assertGe(poolTokenABalanceAfter, pool.reserveA(), "pool reserveA exceeds actual balance -- drained");
        assertGe(poolTokenBBalanceAfter, pool.reserveB(), "pool reserveB exceeds actual balance -- drained");
    }
}
